    exos: [{"type":"true_false","prompt":"Vrai ou faux ?","payload":{"statement":"Les expéditions de champagne ont augmenté en 2024 et en 2025.","answer":false},"explanation":"Elles reculent depuis 2023 : environ 271 millions de bouteilles en 2024, environ 266 millions en 2025."},{"type":"mcq_single","prompt":"Quelle part des volumes de champagne part à l’export ?","payload":{"options":["Un peu plus de la moitié","Environ 10 %","Environ un quart","Plus de 90 %"],"answer":0},"explanation":"L’export a dépassé la France ; les maisons y réalisent l’essentiel de leurs ventes."},{"type":"explain_client","prompt":"Pourquoi trouve-t-on des champagnes de vignerons à côté des grandes marques ?","payload":{"model":"En Champagne, ce sont les vignerons qui possèdent l’essentiel des vignes, environ 90 %. La plupart vendent leurs raisins aux maisons ou aux coopératives ; les grandes maisons font les marques connues et vendent la majorité des bouteilles, surtout à l’étranger. Mais certains vinifient et vendent leur propre champagne : on les reconnaît aux lettres RM sur l’étiquette. Ils vendent surtout en France.","criteria":["Les vignerons possèdent la plupart des vignes, les maisons vendent la plupart des bouteilles","Le code RM signale un vigneron qui fait son propre champagne","Mots simples, pas de jargon sans explication"]}}],
